#!/bin/sh
# apply-schema.sh — apply the generated schema to the running MySQL pod.
#
#   deploy/scripts/apply-schema.sh [path/to/create.sql]
#
# Default source:
#   code/backend/metiche/core/repository/sql/schema/create.sql
# which is generated by nuzur codegen and committed. It is every statement in
# the data model, all of them CREATE TABLE IF NOT EXISTS, so running this
# twice is a no-op and running it after a codegen adds the new tables.
#
# WHAT IT DOES NOT DO: it does not migrate. `CREATE TABLE IF NOT EXISTS` adds
# tables that are missing and silently leaves alone a table whose definition
# has CHANGED — a new column on an existing entity will not appear. When the
# schema evolves against real data, that is an ALTER you write and apply
# deliberately. Finding out the hard way is a lot worse than reading it here.
#
# WHY NOT AN initdb ConfigMap: the mysql image runs /docker-entrypoint-initdb.d
# exactly once, on an empty datadir. That makes the schema un-re-appliable
# after the first boot and turns every codegen into "delete the volume". A
# script you can run whenever is strictly better.
#
# ─────────────────────────────────────────────────────────────────────────────
# THE PASSWORD NEVER APPEARS ANYWHERE
#
# The root password is already inside the MySQL pod, as an environment
# variable the image put there from the Secret. So the shell that runs `mysql`
# runs INSIDE that pod and takes the password out of its own environment:
#
#   kubectl exec ... -- sh -c 'export MYSQL_PWD="$MYSQL_ROOT_PASSWORD"; exec mysql ...'
#
# The password is not in this script, not in argv on the box, not in argv
# inside the pod, and not on this machine at all. MYSQL_PWD rather than -p so
# it is not on the mysql client's command line either.
# ─────────────────────────────────────────────────────────────────────────────

set -eu
. "$(dirname -- "$0")/lib.sh"

case "${1:-}" in
    -h|--help) sed -n '2,40p' "$0"; exit 0 ;;
esac

SCHEMA="${1:-${METICHE_REPO_ROOT}/code/backend/metiche/core/repository/sql/schema/create.sql}"
[ -f "${SCHEMA}" ] || die "schema not found: ${SCHEMA}
The generated tree may not have landed yet. Pass the path explicitly if it moved."

need_cmd "${KUBECTL}" "Install kubectl, or set KUBECTL='microk8s kubectl'."

step "Finding the MySQL pod in namespace ${METICHE_NAMESPACE}"
POD=$(mysql_pod)
[ -n "${POD}" ] || die "no metiche-mysql pod found in ${METICHE_NAMESPACE}. Deploy the metiche-mysql chart first."
log "pod: ${POD}"

step "Waiting for it to be ready"
# Ready means its own probe got a pong out of mysqladmin, so the server is up
# and accepting TCP — not merely that the container started.
kube wait --for=condition=ready "pod/${POD}" --timeout=300s

step "Applying $(basename "${SCHEMA}")"
log "source: ${SCHEMA}"
log "statements: $(grep -c 'CREATE TABLE' "${SCHEMA}" || true) CREATE TABLE"

# --database from the pod's own MYSQL_DATABASE, so the database name is not
# duplicated between here and the chart. The SQL arrives on stdin.
kube exec -i "${POD}" -c mysql -- sh -c '
    set -e
    export MYSQL_PWD="$MYSQL_ROOT_PASSWORD"
    exec mysql --user=root --database="$MYSQL_DATABASE" --batch
' < "${SCHEMA}"

step "Verifying"
# A COUNT and nothing else. No script here ever SELECTs a row: the database
# holds join codes, agent token hashes and (per docs/MODEL.md) a team's
# webhook URL, and a deploy script is not a place any of those may surface.
TABLES=$(kube exec -i "${POD}" -c mysql -- sh -c '
    set -e
    export MYSQL_PWD="$MYSQL_ROOT_PASSWORD"
    exec mysql --user=root --batch --skip-column-names --database="$MYSQL_DATABASE" --execute="SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE();"
' 2>/dev/null) || TABLES=""
if [ -n "${TABLES}" ]; then
    log "${TABLES} tables present in the metiche database"
else
    warn "verification query failed; check: kubectl -n ${METICHE_NAMESPACE} logs ${POD}"
fi

step "Done"
log "The application user (metiche) was created by the mysql image on first"
log "boot with ALL PRIVILEGES on this database, so no GRANT is needed here."
